import { Clock, Effect, Redacted, Schema } from "effect";
import { HttpClientRequest } from "effect/http";
import { RequestExecutor } from "../route/executor.js";
import { AIError, InvalidProviderOutputError, InvalidRequestError } from "../schema/index.js";
import { encodeJson } from "../utils/json.js";
const OPENAI_BASE_URL = "https://api.openai.com/v1";
const XAI_BASE_URL = "https://api.x.ai/v1";
const GOOGLE_BASE_URL = "https://generativelanguage.googleapis.com/v1beta";
const engines = [
    { family: "gpt-live", id: "openai-live", provider: "openai" },
    { family: "gpt-realtime", id: "openai-realtime", provider: "openai" },
    { family: "grok-voice", id: "xai-realtime", provider: "xai" },
    { family: "gemini-3.8-live", id: "gemini-live", provider: "google" },
];
// Matches the bare family name (`gpt-realtime`) and its versions (`gpt-realtime-2.1`, `gpt-realtime-mini`).
export const engine = (model) => engines.find((item) => model === item.family || model.startsWith(`${item.family}-`));
export const connect = Effect.fn("Realtime.connect")(function* (input) {
    const resolved = engine(input.model);
    if (!resolved)
        return yield* invalidRequest(`Unsupported voice model: ${input.model}`);
    const session = { ...input.session, model: input.model };
    switch (resolved.id) {
        case "openai-live": {
            if (input.transport.type !== "webrtc")
                return yield* invalidRequest("OpenAI GPT-Live only supports WebRTC transport");
            const data = yield* post(resolved.id, `${OPENAI_BASE_URL}/live/sessions`, input.apiKey, { session, transport: input.transport }, LiveSessionResponse);
            return { type: "webrtc", sdp: data.transport.sdp };
        }
        case "openai-realtime": {
            if (input.transport.type === "websocket")
                return yield* clientSecret(resolved.id, OPENAI_BASE_URL, input.model, input.apiKey, {
                    expires_after: { anchor: "created_at", seconds: 60 },
                    session,
                });
            const form = new FormData();
            form.append("sdp", input.transport.sdp);
            form.append("session", encodeJson(session));
            const query = input.transport.dcid === undefined ? "" : `?dcid=${input.transport.dcid}`;
            const sdp = yield* post(resolved.id, `${OPENAI_BASE_URL}/realtime/calls${query}`, input.apiKey, form, Schema.String);
            return { type: "webrtc", sdp };
        }
        case "xai-realtime": {
            if (input.transport.type !== "websocket")
                return yield* invalidRequest("xAI Grok Voice only supports WebSocket transport");
            return yield* clientSecret(resolved.id, XAI_BASE_URL, input.model, input.apiKey, {
                expires_after: { seconds: 60 },
            });
        }
        case "gemini-live": {
            if (input.transport.type !== "websocket")
                return yield* invalidRequest("Google Gemini Live only supports WebSocket transport");
            const now = yield* Clock.currentTimeMillis;
            const expiresAt = now + 60_000;
            const data = yield* post(resolved.id, `${GOOGLE_BASE_URL}/auth_tokens`, input.apiKey, {
                uses: 1,
                expireTime: new Date(now + 30 * 60_000).toISOString(),
                newSessionExpireTime: new Date(expiresAt).toISOString(),
                bidiGenerateContentSetup: { ...input.session, model: `models/${input.model}` },
            }, AuthTokenResponse, "x-goog-api-key");
            return {
                type: "websocket",
                url: "wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContentConstrained",
                token: data.name,
                expiresAt: Math.floor(expiresAt / 1000),
            };
        }
    }
});
export const Realtime = {
    engine,
    connect,
};
const LiveSessionResponse = Schema.fromJsonString(Schema.Struct({
    transport: Schema.Struct({ sdp: Schema.String }),
}));
// xAI's ephemeral-token docs (https://docs.x.ai/developers/model-capabilities/audio/ephemeral-tokens)
// document the request body (`{ expires_after: { seconds } }`, no `anchor` or `session`) but not the response payload; we assume
// it mirrors OpenAI's `{ value, expires_at }` response shape.
const ClientSecretResponse = Schema.fromJsonString(Schema.Struct({
    value: Schema.String,
    expires_at: Schema.Number,
}));
const AuthTokenResponse = Schema.fromJsonString(Schema.Struct({
    name: Schema.String,
}));
const invalidRequest = (message) => new AIError({ reason: new InvalidRequestError({ message }) });
const post = (route, url, apiKey, body, response, authHeader) => Effect.gen(function* () {
    const executor = yield* RequestExecutor.Service;
    const res = yield* executor.execute(HttpClientRequest.post(url).pipe(authHeader
        ? HttpClientRequest.setHeader(authHeader, Redacted.value(apiKey))
        : HttpClientRequest.bearerToken(apiKey), body instanceof FormData
        ? HttpClientRequest.bodyFormData(body)
        : HttpClientRequest.bodyText(encodeJson(body), "application/json")));
    const http = RequestExecutor.responseHttp(res);
    const fail = (message, cause, raw) => new AIError({ reason: new InvalidProviderOutputError({ route, message, body: raw, http, cause }) });
    const text = yield* res.text.pipe(Effect.mapError((cause) => fail(`Failed to read ${route} response`, cause)));
    return yield* Schema.decodeEffect(response)(text).pipe(Effect.mapError((cause) => fail(`${route} returned an invalid response`, cause, text)));
});
const clientSecret = (route, baseURL, model, apiKey, body) => post(route, `${baseURL}/realtime/client_secrets`, apiKey, body, ClientSecretResponse).pipe(Effect.map((data) => ({
    type: "websocket",
    url: `${baseURL.replace(/^http/, "ws")}/realtime?model=${encodeURIComponent(model)}`,
    token: data.value,
    expiresAt: data.expires_at,
})));
